import java.util.*;

class MCFGraphIntCost {

    private int n;
    private List<int[]> pos;
    private List<List<Edge>> g;
    private int[] dual, dist, pv, pe;
    private boolean[] vis;

    public MCFGraphIntCost(int n) {
        this.n = n;
        this.pos = new ArrayList<>();
        this.g = new ArrayList<>();
        for (int i = 0; i < n; i++) {
            g.add(new ArrayList<>());
        }
    }

    public int addEdge(int from, int to, int cap, int cost) {
        int m = pos.size();
        pos.add(new int[]{from, g.get(from).size()});
        g.get(from).add(new Edge(to, g.get(to).size(), cap, cost));
        g.get(to).add(new Edge(from, g.get(from).size() - 1, 0, -cost));
        return m;
    }

    public Edge getEdge(int i) {
        int[] p = pos.get(i);
        Edge e = g.get(p[0]).get(p[1]);
        Edge re = g.get(e.to).get(e.rev);
        return new Edge(p[0], e.to, e.cap + re.cap, re.cap, e.cost);
    }

    public List<Edge> edges() {
        List<Edge> ret = new ArrayList<>();
        for (int i = 0; i < pos.size(); i++) {
            int[] p = pos.get(i);
            Edge e = g.get(p[0]).get(p[1]);
            Edge re = g.get(e.to).get(e.rev);
            ret.add(new Edge(p[0], e.to, e.cap + re.cap, re.cap, e.cost));
        }
        return ret;
    }

    private boolean dualRef(int s, int t) {
        dist = new int[n];
        pv = new int[n];
        pe = new int[n];
        vis = new boolean[n];
        Arrays.fill(dist, Integer.MAX_VALUE);
        Arrays.fill(pv, -1);
        Arrays.fill(pe, -1);
        Arrays.fill(vis, false);

        PriorityQueue<Integer> que = new PriorityQueue<>(Comparator.comparingInt(x -> dist[x]));
        dist[s] = 0;
        que.add(s);
        while (!que.isEmpty()) {
            int v = que.poll();
            if (vis[v]) continue;
            vis[v] = true;
            if (v == t) break;
            List<Edge> edges = g.get(v);
            for (int i = 0; i < edges.size(); i++) {
                Edge e = edges.get(i);
                if (vis[e.to] || e.cap == 0) continue;
                int cost = e.cost - dual[e.to] + dual[v];
                if (dist[e.to] > dist[v] + cost) {
                    dist[e.to] = dist[v] + cost;
                    pv[e.to] = v;
                    pe[e.to] = i;
                    que.add(e.to);
                }
            }
        }
        if (!vis[t]) return false;
        for (int v = 0; v < n; v++) {
            if (vis[v]) {
                dual[v] -= dist[t] - dist[v];
            }
        }
        return true;
    }

    public List<long[]> slope(int s, int t, long flowLimit) {
        dual = new int[n];
        dist = new int[n];
        pv = new int[n];
        pe = new int[n];
        vis = new boolean[n];

        long flow = 0;
        long cost = 0;
        long prevCost = -1;
        List<long[]> result = new ArrayList<>();
        result.add(new long[]{flow, cost});

        while (flow < flowLimit) {
            if (!dualRef(s, t)) break;

            long c = flowLimit - flow;
            int v = t;
            while (v != s) {
                int p = pv[v];
                int eIndex = pe[v];
                c = Math.min(c, g.get(p).get(eIndex).cap);
                v = p;
            }

            v = t;
            while (v != s) {
                int p = pv[v];
                int eIndex = pe[v];
                Edge e = g.get(p).get(eIndex);
                g.get(p).get(eIndex).cap -= c;
                g.get(v).get(e.rev).cap += c;
                v = p;
            }

            long d = -dual[s];
            flow += c;
            cost += c * d;

            if (prevCost == d) {
                result.remove(result.size() - 1);
            }
            result.add(new long[]{flow, cost});
            prevCost = cost;
        }
        return result;
    }

    public long[] flow(int s, int t, long flowLimit) {
        List<long[]> res = slope(s, t, flowLimit);
        long[] last = res.get(res.size() - 1);
        return new long[]{last[0], last[1]};
    }

    static class Edge {
        int to;
        int rev;
        int cap;
        int cost;

        Edge(int to, int rev, int cap, int cost) {
            this.to = to;
            this.rev = rev;
            this.cap = cap;
            this.cost = cost;
        }

        Edge(int from, int to, int cap, int rev, int cost) {
            this.to = to;
            this.rev = rev;
            this.cap = cap;
            this.cost = cost;
        }
    }
}

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        final int INF = 1000000000;

        int n = sc.nextInt();
        int a1 = sc.nextInt();
        int a2 = sc.nextInt();
        int a3 = sc.nextInt();
        int b1 = sc.nextInt();
        int b2 = sc.nextInt();
        int b3 = sc.nextInt();

        MCFGraphIntCost g = new MCFGraphIntCost(8);
        g.addEdge(0, 1, a1, 0);
        g.addEdge(0, 2, a2, 0);
        g.addEdge(0, 3, a3, 0);
        g.addEdge(4, 7, b1, 0);
        g.addEdge(5, 7, b2, 0);
        g.addEdge(6, 7, b3, 0);

        for (int i = 1; i <= 3; i++) {
            for (int j = 4; j <= 6; j++) {
                int cost = ((j - i) % 3 == 1) ? 1 : 0;
                g.addEdge(i, j, INF, cost);
            }
        }

        long[] flowRes = g.flow(0, 7, INF);
        long ans1 = flowRes[1];

        long ans2 = Math.min(a1, b2) + Math.min(a2, b3) + Math.min(a3, b1);

        System.out.println(ans1 + " " + ans2);
    }
}

import java.util.*;
import java.io.*;

public class Main {
    static int mod = 998244353;
    static int n;
    static int[] rock1, sci1, paper1;
    static int[] rock2, sci2, paper2;

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        n = sc.nextInt();
        rock1 = new int[] {sc.nextInt(), sc.nextInt(), sc.nextInt()};
        sci1 = new int[] {sc.nextInt(), sc.nextInt(), sc.nextInt()};
        paper1 = new int[] {sc.nextInt(), sc.nextInt(), sc.nextInt()};

        rock2 = new int[] {sc.nextInt(), sc.nextInt(), sc.nextInt()};
        sci2 = new int[] {sc.nextInt(), sc.nextInt(), sc.nextInt()};
        paper2 = new int[] {sc.nextInt(), sc.nextInt(), sc.nextInt()};

        System.out.println(minimum() + " " + maximum());
        sc.close();
    }

    static int maximum() {
        int ans = Math.min(rock1[0], sci2[0]) + Math.min(sci1[0], paper2[0]) + Math.min(paper1[0], rock2[0]);
        return ans;
    }

    static int match(int a, int b) {
        if (a == b) return 0;
        if ((a == 1 && b == 2) || (a == 2 && b == 3) || (a == 3 && b == 1))
            return 1;
        return -1;
    }

    static int give(List<int[]> l1, List<int[]> l2) {
        int ans = 0;
        int curr1Count = 0, curr2Count = 0;
        int[] curr1 = null, curr2 = null;
        Stack<int[]> stack1 = new Stack<>();
        Stack<int[]> stack2 = new Stack<>();
        for (int[] val : l1) stack1.push(val);
        for (int[] val : l2) stack2.push(val);
        // Convert to deque for easier pop from end
        ArrayDeque<int[]> dq1 = new ArrayDeque<>(stack1);
        ArrayDeque<int[]> dq2 = new ArrayDeque<>(stack2);

        while (!dq1.isEmpty() || !dq2.isEmpty()) {
            try {
                if (curr1 == null) {
                    curr1 = dq1.pollLast();
                }
                if (curr2 == null) {
                    curr2 = dq2.pollLast();
                }
            } catch (NoSuchElementException e) {
                break;
            }

            int minCount = Math.min(curr1[0], curr2[0]);
            int m = match(curr1[1], curr2[1]);
            ans += Math.max(0, minCount * m);

            if (curr1[0] < curr2[0]) {
                curr2[0] -= curr1[0];
                curr1 = null;
            } else if (curr1[0] > curr2[0]) {
                curr1[0] -= curr2[0];
                curr2 = null;
            } else {
                curr1 = null;
                curr2 = null;
            }
        }
        return ans;
    }

    static int minimum() {
        int ans = n;
        List<int[]> l = new ArrayList<>();
        l.add(new int[] {rock1[0], 1});
        l.add(new int[] {sci1[0], 2});
        l.add(new int[] {paper1[0], 3});

        List<int[]> l2 = new ArrayList<>();
        l2.add(new int[] {rock2[0], 1});
        l2.add(new int[] {sci2[0], 2});
        l2.add(new int[] {paper2[0], 3});

        List<List<int[]>> permutationsL1 = generatePermutations(l);
        List<List<int[]>> permutationsL2 = generatePermutations(l2);

        int minAns = Integer.MAX_VALUE;
        for (List<int[]> perm1 : permutationsL1) {
            for (List<int[]> perm2 : permutationsL2) {
                List<int[]> list1 = new ArrayList<>();
                for (int[] item : perm1) {
                    list1.add(new int[] {item[0], item[1]});
                }

                List<int[]> list2 = new ArrayList<>();
                for (int[] item : perm2) {
                    list2.add(new int[] {item[0], item[1]});
                }

                minAns = Math.min(minAns, give(list1, list2));
            }
        }
        return minAns;
    }

    static List<List<int[]>> generatePermutations(List<int[]> list) {
        List<List<int[]>> result = new ArrayList<>();
        permute(list, 0, result);
        return result;
    }

    static void permute(List<int[]> arr, int k, List<List<int[]>> result) {
        if (k == arr.size() - 1) {
            List<int[]> temp = new ArrayList<>();
            for (int[] a : arr)
                temp.add(new int[]{a[0], a[1]});
            result.add(temp);
        } else {
            for (int i = k; i < arr.size(); i++) {
                Collections.swap(arr, i, k);
                permute(arr, k + 1, result);
                Collections.swap(arr, i, k);
            }
        }
    }
}

import java.util.*;
import java.io.*;

public class Main {
    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        int n = Integer.parseInt(br.readLine().trim());
        int[] inputA = Arrays.stream(br.readLine().trim().split(" ")).mapToInt(Integer::parseInt).toArray();
        int[] inputB = Arrays.stream(br.readLine().trim().split(" ")).mapToInt(Integer::parseInt).toArray();

        int[] inputA2 = inputA.clone();
        int[] inputB2 = inputB.clone();

        System.out.println((n - getLostMaxFast(inputA2, inputB2)) + " " + getWonMaxFast(inputA, inputB));
    }

    private static int getWonMaxFast(int[] inputA, int[] inputB) {
        int[] wins = {0, 0, 0};
        for (int i = 0; i < 3; i++) {
            int good = (i + 1) % 3;
            wins[i] = Math.min(inputA[i], inputB[good]);
            inputA[i] -= wins[i];
            inputB[good] -= wins[i];
        }
        int sum = 0;
        for (int w : wins) {
            sum += w;
        }
        return sum;
    }

    private static int getLostMaxFast(int[] inputA, int[] inputB) {
        int[][][] waysToLose = {
            {{0, 2}},
            {{1, 0}},
            {{2, 1}},
            {{0, 0}},
            {{1, 1}},
            {{2, 2}}
        };
        List<int[][]> allPermutations = new ArrayList<>();
        generatePermutations(waysToLose, 0, allPermutations);
        int maxLost = 0;

        for (int[][] permutation : allPermutations) {
            int[] losts = {0, 0, 0};
            int[] inputACopy = inputA.clone();
            int[] inputBCopy = inputB.clone();
            for (int[] wayToLose : permutation) {
                int lost_add = Math.min(inputACopy[wayToLose[0]], inputBCopy[wayToLose[1]]);
                inputACopy[wayToLose[0]] -= lost_add;
                inputBCopy[wayToLose[1]] -= lost_add;
                losts[wayToLose[0]] += lost_add;
            }
            int lostSum = 0;
            for (int l : losts) {
                lostSum += l;
            }
            if (lostSum > maxLost) {
                maxLost = lostSum;
            }
        }
        return maxLost;
    }

    private static void generatePermutations(int[][][] ways, int index, List<int[][]> permutations) {
        if (index == ways.length) {
            int[][] permutation = new int[ways.length][2];
            for (int i=0; i<ways.length; i++) {
                permutation[i][0] = ways[i][0][0];
                permutation[i][1] = ways[i][0][1];
            }
            permutations.add(permutation);
            return;
        }
        for (int i = 0; i < ways.length; i++) {
            generatePermutations(ways, index + 1, permutations);
        }
    }
}

