        long modpow(long a, long p) {
            long ans = 1;
            while (p > 0) {
                if ((p & 1) != 0) {
                    ans = (ans * a) % MOD;
                }
                p >>= 1;
                a = (a * a) % MOD;
            }
            return ans;
        }

        long fac_cal(int n) {
            long ans = 1;
            for (int i = 1; i <= n; i++) {
                ans = (ans * i) % MOD;
            }
            return ans;
        }

        void solve() throws IOException {
            int n = giveInt();
            int[] a = giveList();
            int[] b = giveList();

            List<int[]> permutations = generatePermutations(new int[]{1, 2, 3, 4, 5, 6});
            int minMx = Integer.MAX_VALUE;
