                            ta1 -= t1;
                            tb3 -= t1;
                            tmx += t1;
                            break;
                        case 3:
                            t1 = Math.min(ta2, tb2);
                            ta2 -= t1;
                            tb2 -= t1;
                            tmx += t1;
                            break;
                        case 4:
                            t1 = Math.min(ta2, tb1);
                            ta2 -= t1;
                            tb1 -= t1;
                            tmx += t1;
