            // Let's track the maximum 'tmx' among all permutations.

            // So, define a variable outside the loop:
        }

        List<int[]> generatePermutations(int[] nums) {
            List<int[]> perms = new ArrayList<>();
            permute(nums, 0, perms);
            return perms;
        }

        void permute(int[] arr, int l, List<int[]> perms) {
            if (l == arr.length - 1) {
