import java.util.*;
import java.io.*;

public class Main {
    static final long INF = 1000000000000000000L;

    static int input() {
        try {
            BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
            return Integer.parseInt(br.readLine().trim());
        } catch (Exception e) {
            return 0;
        }
    }

    static List<Integer> LIST() {
        try {
            BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
            String[] parts = br.readLine().split("\\s+");
            List<Integer> list = new ArrayList<>();
            for (String p : parts) {
                list.add(Integer.parseInt(p));
            }
            return list;
        } catch (Exception e) {
            return Collections.emptyList();
        }
    }

    static class Dinic {
        int n;
        List<List<long[]>> links;
        int[] depth;
        int[] progress;
        List<int[]> pos;

        public Dinic(int n) {
            this.n = n;
            links = new ArrayList<>();
            for (int i = 0; i < n; i++) {
                links.add(new ArrayList<>());
            }
            pos = new ArrayList<>();
        }

        public Dinic copy() {
            Dinic res = new Dinic(n);
            for (int i = 0; i < n; i++) {
                List<long[]> originalLinks = links.get(i);
                List<long[]> newLinks = new ArrayList<>();
                for (long[] link : originalLinks) {
                    newLinks.add(link.clone());
                }
                res.links.set(i, newLinks);
            }
            res.pos = new ArrayList<>();
            for (int[] p : pos) {
                res.pos.add(p.clone());
            }
            return res;
        }

        public void addEdge(int from, int to, long cap) {
            pos.add(new int[]{from, links.get(from).size()});
            links.get(from).add(new long[]{cap, to, links.get(to).size()});
            links.get(to).add(new long[]{0, from, links.get(from).size() - 1});
        }

        public void bfs(int s) {
            depth = new int[n];
            Arrays.fill(depth, -1);
            depth[s] = 0;
            Queue<Integer> q = new LinkedList<>();
            q.offer(s);
            while (!q.isEmpty()) {
                int v = q.poll();
                for (long[] link : links.get(v)) {
                    long cap = link[0];
                    int to = (int) link[1];
                    if (cap > 0 && depth[to] < 0) {
                        depth[to] = depth[v] + 1;
                        q.offer(to);
                    }
                }
            }
        }

        public long dfs(int v, int t, long flow) {
            if (v == t)
                return flow;
            List<long[]> linksV = links.get(v);
            for (; progress[v] < linksV.size(); progress[v]++) {
                long[] link = linksV.get(progress[v]);
                long cap = link[0];
                int to = (int) link[1];
                int rev = (int) link[2];
                if (cap == 0 || depth[v] >= depth[to])
                    continue;
                long d = dfs(to, t, Math.min(flow, cap));
                if (d == 0)
                    continue;
                link[0] -= d;
                links.get(to).get(rev)[0] += d;
                return d;
            }
            return 0;
        }

        public long flow(int s, int t) {
            long flowVal = 0;
            while (true) {
                bfs(s);
                if (depth[t] < 0)
                    return flowVal;
                progress = new int[n];
                long currentFlow = dfs(s, t, INF);
                while (currentFlow > 0) {
                    flowVal += currentFlow;
                    currentFlow = dfs(s, t, INF);
                }
            }
        }

        public int[] getEdge(int i) {
            int[] p = pos.get(i);
            long[] e = links.get(p[0]).get(p[1]);
            long[] re = links.get((int) e[1]).get((int) e[2]);
            return new int[]{p[0], (int) e[1], (int) (e[0] + re[0]), (int) re[0]};
        }

        public List<int[]> getEdges() {
            List<int[]> res = new ArrayList<>();
            for (int i = 0; i < pos.size(); i++) {
                res.add(getEdge(i));
            }
            return res;
        }
    }

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        int N = Integer.parseInt(br.readLine().trim());
        int M = 3;
        List<Integer> A = new ArrayList<>();
        List<Integer> B = new ArrayList<>();
        {
            String[] parts = br.readLine().split("\\s+");
            for (String p : parts) {
                A.add(Integer.parseInt(p));
            }
        }
        {
            String[] parts = br.readLine().split("\\s+");
            for (String p : parts) {
                B.add(Integer.parseInt(p));
            }
        }

        int ans1 = 0;
        for (int i = 0; i < M; i++) {
            ans1 += Math.min(A.get(i), B.get((i + 1) % M));
        }

        int ans2 = 0;
        Dinic dinic = new Dinic(2 * M + 2);
        int s = 2 * M;
        int t = 2 * M + 1;
        for (int i = 0; i < M; i++) {
            // s to Alice
            dinic.addEdge(s, i, N);
            // Bob to t
            dinic.addEdge(M + i, t, B.get(i));
            // draw
            dinic.addEdge(i, M + i, A.get(i));
            // Alice lose
            dinic.addEdge(i, M + ((i - 1 + M) % M), A.get(i));
        }
        ans2 = N - (int) dinic.flow(s, t);

        System.out.println(ans2 + " " + ans1);
    }
}

