public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        // Read integers n and mod
        int n = sc.nextInt();
        int mod = sc.nextInt();

        // Initialize mem array and su variable
        long[] mem = new long[n + 1];
        mem[0] = 0;
        mem[1] = 1;
        long su = 1;

        // Helper functions
        java.util.function.BiFunction<Long, Long, Long> add = (a, b) -> (a + b) % mod;
        java.util.function.BiFunction<Long, Long, Long> mult = (a, b) -> (a * b) % mod;

        for (int i = 2; i <= n; i++) {
            int sq = (int)(Math.sqrt(i)) + 1;
            long cur = su;

            // For loop for range 2 to sq
            for (int f = 2; f < sq; f++) {
                long index = i / f;
                // Ensure index within bounds
                if (index < mem.length) {
                    cur = add.apply(cur, mem[(int)index]);
                }
            }

            long be = i;
            // Loop for j in 1 to i / sq
            for (int j = 1; j <= i / sq; j++) {
                long nxt = i / (j + 1);
                long addend = (be - nxt);
                if (addend < 0) addend += mod; // ensure non-negative before multiplication
                long temp = mult.apply(addend, mem[(int)j]);
                cur = add.apply(cur, temp);
                be = nxt;
            }

            su = add.apply(su, cur);
            mem[i] = cur;
        }

        System.out.println(mem[n]);
        sc.close();
    }
}

import java.util.Scanner;

public class Main {
    static final long M = 1000000007L;

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        int T = 1; // As per the original code, T is fixed at 1
        for (int testCase = 0; testCase < T; testCase++) {
            process(scanner);
        }
        scanner.close();
    }

    static void process(Scanner scanner) {
        int P = scanner.nextInt();
        int K = scanner.nextInt();

        int[] k = new int[P];
        for (int x = 0; x < P; x++) {
            k[x] = (int)(((long)K * x) % P);
        }

        if (K == 0) {
            System.out.println(modPow(P, P - 1, M));
            return;
        }
        if (K == 1) {
            System.out.println(modPow(P, P, M));
            return;
        }

        int[] f = new int[P];
        int[] c = new int[P];
        long ans = 1;

        for (int i = 0; i < P; i++) {
            if (f[i] != 0) continue;
            int cnt = 1;
            int u = i;
            f[u] = 1;
            while (f[k[u]] == 0) {
                u = k[u];
                f[u] = 1;
                cnt++;
            }
            c[cnt]++;
        }

        for (int i = 2; i < P; i++) {
            if (c[i] != 0) {
                int cnt = i * c[i] + 1;
                ans = (ans * modPow(cnt, c[i], M)) % M;
            }
        }

        System.out.println(ans);
    }

    static long modPow(long base, long exp, long mod) {
        long result = 1;
        long curr = base % mod;
        long e = exp;
        while (e > 0) {
            if ((e & 1) == 1) {
                result = (result * curr) % mod;
            }
            curr = (curr * curr) % mod;
            e >>= 1;
        }
        return result;
    }
}

