            currentPower = (currentPower * currentPower) % mod;
            exp >>= 1;
        }
        return result;
    }

    public static List<Integer> divisors(int n) {
        Set<Integer> set = new HashSet<>();
        int i = 1;
        while (i * i <= n) {
            if (n % i == 0) {
                set.add(i);
                set.add(n / i);
            }
            i++;
        }
        List<Integer> list = new ArrayList<>(set);
        Collections.sort(list);
        return list;
    }
}

