        final int MOD = (int) 1e9 + 7;
        Scanner scanner = new Scanner(System.in);
        int n = scanner.nextInt();
        int k = scanner.nextInt();
        long p;
        if (k < 2) {
            p = n - (1 - k);
        } else {
            long t = 1;
            long a = k;
            while (a != 1) {
                a = (a * k) % n;
                t += 1;
            }
            p = (n - 1) / t;
        }
        System.out.println(powMod(n, p, MOD));
        scanner.close();
    }

    private static long powMod(long base, long exp, int mod) {
        long result = 1;
        base = base % mod;
        while (exp > 0) {
            if ((exp & 1) == 1) {
                result = (result * base) % mod;
            }
            base = (base * base) % mod;
            exp >>= 1;
        }
        return result;
    }
}

