        for (int i = 1; i <= 50; i++) {
            sl[i] = sl[i - 1] + (1 << i);
        }

        int h = sc.nextInt();
        int n_input = sc.nextInt();

        List<Integer> nl = new ArrayList<>();
        int n = n_input + sl[h - 1];
        int tn = n;
        nl.add(tn);

        while (tn != 1) {
            tn = tn / 2;
            nl.add(tn);
        }

        int ans = 0;
        int cn = 1;
        boolean cp = false;

        while (cn != n) {
            List<Integer> tnl = new ArrayList<>();
            int temp_cn = cn; // to preserve cn for computations
            for (int i = 0; i < h; i++) {
                tnl.add(temp_cn);
                if (!cp) {
