                    temp_cn = temp_cn * 2 + 1;
                }
                cp = !cp;
            }
            if (temp_cn == n) {
                ans += h;
                break;
            }
            tnl.add(temp_cn);
            Collections.reverse(tnl);
            boolean breakOuter = false;
            for (int i = 1; i <= h; i++) {
                if (nl.get(i).equals(tnl.get(i))) {
