public class Main {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        String rs = scanner.nextLine();
        String s = rs.substring(1, rs.length() - 1);
        int l = s.length();
        StringBuilder res = new StringBuilder();
        res.append(rs.charAt(0));
        int i = 0;
        boolean findAt = false;
        while (i < l) {
            if (i + 3 <= l) {
                if (s.substring(i, i + 3).equals("dot")) {
                    res.append(".");
                    i += 3;
                    continue;
                }
            }
            if (i + 2 <= l && !findAt) {
                if (s.substring(i, i + 2).equals("at")) {
                    res.append("@");
                    findAt = true;
                    i += 2;
                    continue;
                }
            }
            res.append(s.charAt(i));
            i += 1;
        }
        res.append(rs.charAt(rs.length() - 1));
        System.out.println(res.toString());
        scanner.close();
    }
}

