import java.util.*;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        int m = sc.nextInt();
        int[] a = new int[n];
        for (int i = 0; i < n; i++) {
            a[i] = sc.nextInt();
        }

        List<Integer> b = new ArrayList<>();
        int otv = 0;
        int limit1 = 1 << (n / 2 + n % 2);
        int limit2 = 1 << (n / 2);

        for (int i = 0; i < limit1; i++) {
            int t = 0;
            int k = i;
            for (int j = 0; j < 20; j++) {
                if ((k & 1) != 0) {
                    if (j < a.length)
                        t += a[j];
                }
                k = k >> 1;
            }
            b.add(t % m);
        }

        Collections.sort(b);

        for (int i = 0; i < limit2; i++) {
            int t = 0;
            int k = i;
            for (int j = 0; j < 20; j++) {
                if ((k & 1) != 0) {
                    int index = (n / 2 + n % 2) + j;
                    if (index < a.length)
                        t += a[index];
                }
                k = k >> 1;
            }
            t = t % m;
            int key = Collections.binarySearch(b, m - t - 1);
            int idx;
            if (key >= 0) {
                idx = key;
            } else {
                idx = -key - 1; // insertion point
            }

            int t2;
            if (idx < b.size()) {
                t2 = b.get(idx);
                if (t2 > m - t - 1) {
                    if (idx - 1 >= 0) {
                        t2 = b.get(idx - 1);
                    }
                }
            } else {
                t2 = b.get(b.size() - 1);
            }

            otv = Math.max(otv, Math.max((t + t2) % m, (t + b.get(b.size() - 1)) % m));
        }
        System.out.println(otv % m);
    }
}

