            resultList.add(answer);
        }
        System.out.println(resultList.get(resultList.size() - 1));
    }

    private static void sums1(int[] a, int index, int end, int sum, int m, List<Integer> list) {
        if (index == end) {
            list.add(sum % m);
            return;
        }
        sums1(a, index + 1, end, sum + a[index], m, list);
        sums1(a, index + 1, end, sum, m, list);
    }

    private static void sums2(int[] a, int start, int end, int sum, int m, List<Integer> list) {
        if (start == end) {
            list.add(sum % m);
            return;
        }
        sums2(a, start + 1, end, sum + a[start], m, list);
        sums2(a, start + 1, end, sum, m, list);
    }

    private static int solve(int val, List<Integer> a1, int m) {
        int idx = Collections.binarySearch(a1, m - val);
        if (idx < 0) {
            idx = -idx - 1; // insertion point
        }
        int res = 0;
        if (idx > 0) {
            res = a1.get(idx - 1) + val;
        }
        return res;
    }
}

