public class Solution {

    public static int solve(int n, int mod) {
        if (n <= 3) {
            return 0;
        } else {
            int lastAns = 17;
            int ans = 17;
            int size = (n - 1) * (n - 2) / 2 + 1;
            int inv = 1;
            int[][] record = new int[2][size + 1];

            for (int i = 0; i <= 3; i++) {
                record[0][i] = (i == 0 || i == 3) ? 1 : (i == 1 || i == 2) ? 2 : 0;
            }

            for (int m = 4; m < n; m++) {
                int tpSize = m * (m - 1) / 2;
                ans = (m + 1) * lastAns;
                int tp = 0;

                // Update prefix sums for the current 'inv' state
                for (int i = 0; i < m; i++) {
                    tp += record[inv ^ 1][i];
                    record[inv][i] = tp % mod;
                }

                // Compute the next layer
                for (int i = m; i <= tpSize / 2; i++) {
                    tp += record[inv ^ 1][i];
                    tp -= record[inv ^ 1][i - m];
                    record[inv][i] = tp % mod;
                }

                // Mirror the values to complete symmetric layer
                for (int i = 0; i <= tpSize / 2; i++) {
                    record[inv][tpSize - i] = record[inv][i];
                }

                int total = 0;
                // Calculate contributions for j in given range
                for (int i = 0; i < tpSize; i++) {
                    tp = 0;
                    int start = Math.max(1, -tpSize + i + m + 2);
                    for (int j = start; j <= m; j++) {
                        int valIndex = m + 2 - j + i;
                        if (valIndex >= 0 && valIndex <= tpSize) {
                            tp += j * record[inv][valIndex];
                        }
                    }
                    total += record[inv][i];
                    total %= mod;
                    tp %= mod;
                    ans += (tp * total) % mod;
                    ans %= mod;
                }

                lastAns = ans;
                inv ^= 1;
            }
            return ans % mod;
        }
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
