    static int t(int n, int h) {
        if (dp[n][h] == -1) {
            int sum = 0;
            for (int m = 1; m <= n; m++) {
                int sum1 = 0;
                for (int i = 0; i < h; i++) {
                    sum1 += t(n - m, i);
                }
                int sum2 = 0;
                for (int i = 0; i < h - 1; i++) {
