import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        int n = scanner.nextInt();
        int h = scanner.nextInt();
        scanner.nextLine(); // Consume remaining newline if present

        int[][] dp = new int[n + 1][n + 1];

        // Initialize dp array with -1 indicating uncomputed states
        for (int i = 0; i <= n; i++) {
            for (int j = 0; j <= n; j++) {
                dp[i][j] = -1;
            }
        }

        // Base case
        dp[0][0] = 1;

        int result = f(n, h, dp);
        System.out.println(result);
        scanner.close();
    }

    public static int f(int n, int h, int[][] dp) {
        if (dp[n][h] != -1) {
            return dp[n][h];
        }

        if (n == 0) {
            return 0;
        }
        if (h == 0) {
            dp[n][h] = f(n, 1, dp);
            return dp[n][h];
        }

        long ans = 0; // Use long to avoid overflow during calculations
        for (int i = 0; i < n; i++) {
            ans += (long)f(n - i - 1, 0, dp) * f(i, h - 1, dp);
            ans += (long)f(n - i - 1, h - 1, dp) * f(i, 0, dp);
            ans -= (long)f(n - i - 1, h - 1, dp) * f(i, h - 1, dp);
        }

        // Cast back to int assuming the result fits into int
        dp[n][h] = (int) ans;
        return dp[n][h];
    }
}

